create or replace function app_private.worker_runtime_capability(p_worker_code text) returns text language plpgsql immutable set search_path='' as $function$ declare v_code text:=upper(btrim(coalesce(p_worker_code,''))); begin case v_code when 'LIVETICKER_GRAPHICS' then return 'liveticker.manage'; when 'FANBUS_PUBLISHING' then return 'fanbus.publishing.manage'; else raise exception 'WORKER_CODE_INVALID' using errcode='22023'; end case; end;$function$;
